const sd = $getWorkflowStaticData('global');
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const categorias = [
  { nome: 'Desenvolvimento web com React e TypeScript', imagens: ['code on dark monitor', 'javascript code screen', 'web developer laptop', 'programming workspace', 'colorful code editor', 'frontend developer desk'] },
  { nome: 'Automação de processos com n8n e APIs', imagens: ['workflow diagram', 'automation gears', 'connected network nodes', 'data flow abstract', 'api integration', 'robot arm automation'] },
  { nome: 'Inteligência Artificial aplicada ao desenvolvimento de software', imagens: ['artificial intelligence', 'processor chip', 'neural network abstract', 'robot and human', 'machine learning', 'futuristic technology'] },
  { nome: 'Boas práticas de código e arquitetura de software', imagens: ['whiteboard planning', 'software architecture diagram', 'developer desk setup', 'code review team', 'blueprint plan', 'programming team'] },
  { nome: 'Linux, Docker e infraestrutura para quem desenvolve', imagens: ['server room', 'data center', 'network cables', 'terminal screen', 'cloud computing', 'fiber optic'] },
  { nome: 'Segurança para quem desenvolve software', imagens: ['padlock security', 'cyber security shield', 'password login', 'two factor authentication', 'encryption code', 'fingerprint scanner'] },
  { nome: 'Carreira e produtividade em desenvolvimento de software', imagens: ['home office', 'notebook planner', 'team meeting', 'coffee desk', 'online learning', 'headphones work'] },
];

const formatosManha = [
  'dica rápida com lista curta de 3 a 5 itens',
  'mito x verdade sobre o assunto',
  'erro comum que as pessoas cometem e como evitar',
  'mini passo a passo prático',
  'checklist para o leitor aplicar hoje',
];
const formatosNoite = [
  'curiosidade surpreendente explicada de forma leve, sem números inventados',
  'reflexão em primeira pessoa, sem inventar fatos específicos',
  'explicação simples usando uma analogia do dia a dia',
  'pergunta provocativa seguida da resposta',
  'conversa direta com o leitor, como um conselho a um amigo',
];
// um post por dia: dias pares = dicas práticas, dias ímpares = reflexões
const manha = $now.ordinal % 2 === 0;
const tons = ['didático e calmo', 'descontraído e bem-humorado', 'direto e objetivo', 'curioso e entusiasmado', 'sério e alerta, sem causar pânico'];
const ganchos = ['uma pergunta curiosa', 'uma frase curta e inesperada', 'um erro comum', 'uma situação do cotidiano', 'uma afirmação que quebra um mito', 'um "e se" interessante'];

const ultimas = Array.isArray(sd.ultimasCategorias) ? sd.ultimasCategorias : [];
let candidatas = categorias.filter(c => !ultimas.includes(c.nome));
if (!candidatas.length) candidatas = categorias;
const cat = pick(candidatas);

// evita repetir formato e tipo de abertura dos últimos posts
const semRepetir = (lista, usados) => { const livres = lista.filter(x => !usados.includes(x)); return livres.length ? livres : lista; };
const ultimosFormatos = Array.isArray(sd.ultimosFormatos) ? sd.ultimosFormatos : ['pergunta provocativa seguida da resposta'];
const ultimosGanchos = Array.isArray(sd.ultimosGanchos) ? sd.ultimosGanchos : ['um "e se" interessante', 'uma pergunta curiosa'];
const aberturas = Array.isArray(sd.ultimasAberturas) ? sd.ultimasAberturas : ['E se aquela rede', 'E se a melhor'];

// título de uma página do Notion, em qualquer formato de saída do nó
const tituloDe = (j) => {
  if (!j) return '';
  if (j.properties) {
    for (const p of Object.values(j.properties)) {
      if (p && p.type === 'title' && Array.isArray(p.title)) return p.title.map(t => t.plain_text || '').join('');
    }
  }
  return j.name || j.Name || j.Nome || j.property_name || j.property_nome || j.title || '';
};

const doNotion = $input.all().map(i => String(tituloDe(i.json)).trim()).filter(Boolean);
const memoria = Array.isArray(sd.temas) ? sd.temas : [];
const temas = [...new Set([...memoria, ...doNotion])].slice(0, 80);

return [{
  json: {
    area: cat.nome,
    formato: pick(semRepetir(manha ? formatosManha : formatosNoite, ultimosFormatos)),
    tom: pick(tons),
    gancho: pick(semRepetir(ganchos, ultimosGanchos)),
    aberturasRecentes: aberturas.length ? aberturas.map(t => '- ' + t).join('\n') : '(nenhuma ainda)',
    dicaImagem: pick(cat.imagens),
    temasAnteriores: temas.length ? temas.map(t => '- ' + t).join('\n') : '(nenhum ainda)',
  },
}];

const entrada = $input.first().json;
const tema = $('Montar tema do dia').first().json;

const partes = (entrada.candidates && entrada.candidates[0] && entrada.candidates[0].content && entrada.candidates[0].content.parts) || [];
let txt = partes.filter(p => !p.thought).map(p => p.text || '').join('');
if (typeof txt !== 'string' || !txt.trim()) {
  throw new Error('A IA não devolveu texto (' + JSON.stringify(entrada.promptFeedback || entrada.error || '').slice(0, 200) + '). Verifique a chave do Gemini e o limite diário gratuito.');
}
txt = txt.replace(/\r/g, '').trim();

const pega = (re) => { const r = txt.match(re); return r ? r[1].trim() : ''; };
let titulo = pega(/^\s*T[IÍ]TULO:\s*(.+)$/im);
let busca = pega(/^\s*BUSCA:\s*(.+)$/im);
const iPost = txt.search(/^\s*POST:/im);
let post = iPost >= 0 ? txt.slice(iPost).replace(/^\s*POST:\s*/i, '') : '';

const limparTexto = (s) => String(s || '')
  .replace(/\*\*/g, '')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/[()\[\]{}<>|~*_@\\]/g, ' ')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/ +\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

post = limparTexto(post);
titulo = limparTexto(titulo).replace(/^\s*tecnologia\s*:\s*/i, '').replace(/\n/g, ' ').slice(0, 80).trim();

if (!post || post.length < 200) throw new Error('O post veio vazio ou curto demais (' + post.length + ' caracteres). Resposta da IA: ' + txt.slice(0, 200));
if (!titulo) throw new Error('A IA não devolveu a linha TITULO. Resposta da IA: ' + txt.slice(0, 200));
if (post.length > 2700) {
  const corte = post.lastIndexOf('\n\n', 2700);
  post = post.slice(0, corte > 500 ? corte : 2700).trim();
}

busca = busca.replace(/[^a-zA-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
if (!busca) busca = tema.dicaImagem;

return [{ json: { titulo, post, buscaImagem: busca, area: tema.area } }];

const sd = $getWorkflowStaticData('global');
const usadas = Array.isArray(sd.fotosUsadas) ? sd.fotosUsadas : [];
const idsUsados = new Set(usadas.map(f => String(f.id)));

const lerHits = (nome) => {
  try { const h = $(nome).first().json.hits; return Array.isArray(h) ? h : []; } catch (e) { return []; }
};
const valida = (h) => h && h.id && h.largeImageURL;
const h1 = lerHits('Buscar fotos do tema').filter(valida);
const h2 = lerHits('Buscar fotos de reserva').filter(valida);

const todas = [];
const vistos = new Set();
for (const h of [...h1, ...h2]) { if (!vistos.has(h.id)) { vistos.add(h.id); todas.push(h); } }

if (!todas.length) {
  throw new Error('O Pixabay não retornou fotos. Confira a chave do Pixabay (credencial Query Auth com nome "key") e o limite de requisições.');
}

const livres = (arr) => arr.filter(h => !idsUsados.has(String(h.id)));
let candidatas = livres(h1);
if (!candidatas.length) candidatas = livres(h2);
if (!candidatas.length) {
  // todas já foram usadas: pega a usada há mais tempo
  const ordem = new Map(usadas.map((f, i) => [String(f.id), i]));
  candidatas = [...todas].sort((a, b) => (ordem.get(String(a.id)) ?? -1) - (ordem.get(String(b.id)) ?? -1)).slice(0, 1);
}

const foto = candidatas[Math.floor(Math.random() * candidatas.length)];
const nome = String(foto.user || 'autor desconhecido').replace(/[()\[\]{}<>|~*_@\\#]/g, ' ').replace(/\s+/g, ' ').trim();

return [{ json: { fotoId: foto.id, fotoUrl: foto.largeImageURL, fotografo: nome } }];

const sd = $getWorkflowStaticData('global');
const post = $('Validar e limpar post').first().json;
const foto = $('Escolher foto').first().json;

sd.fotosUsadas = [...(Array.isArray(sd.fotosUsadas) ? sd.fotosUsadas : []), { id: foto.fotoId, data: $today.toFormat('yyyy-MM-dd') }].slice(-300);
sd.temas = [post.titulo, ...(Array.isArray(sd.temas) ? sd.temas : [])].slice(0, 80);
sd.ultimasCategorias = [post.area, ...(Array.isArray(sd.ultimasCategorias) ? sd.ultimasCategorias : [])].slice(0, 3);
const temaDoDia = $('Montar tema do dia').first().json;
sd.ultimosFormatos = [temaDoDia.formato, ...(Array.isArray(sd.ultimosFormatos) ? sd.ultimosFormatos : [])].slice(0, 3);
sd.ultimosGanchos = [temaDoDia.gancho, ...(Array.isArray(sd.ultimosGanchos) ? sd.ultimosGanchos : [])].slice(0, 3);
const abertura = String(post.post || '').trim().split(/\s+/).slice(0, 4).join(' ');
sd.ultimasAberturas = [abertura, ...(Array.isArray(sd.ultimasAberturas) ? sd.ultimasAberturas : ['E se aquela rede', 'E se a melhor'])].slice(0, 6);

return [{ json: { registrado: true, fotoId: foto.fotoId, titulo: post.titulo } }];
